 Db db; LinearLayout root,body; String screen="Startseite",filter="Monat",search=""; long customerId=-1,projectId=-1,editId=-1; boolean dark=false; long timerStart=0; static final int PDF=10,XLSX=11,BACKUP=12,RESTORE=13,LOGO=14,BACKUP_FOLDER=15,PROJECT_UPLOAD=16,FULL_BACKUP=17,FULL_RESTORE=18; Uri logo; String uploadKind="Dokument"; String selectedDay=today(); Calendar calendarMonth=Calendar.getInstance(); String calendarView="Monat",rangeFrom="",rangeTo=""; float gestureX,gestureY; boolean gestureSwiped=false; float calendarZoom=1f; android.view.ScaleGestureDetector calendarScale; boolean pinchInProgress=false; java.util.ArrayDeque<String> backHistory=new java.util.ArrayDeque<>(); boolean navigatingBack=false;
 int bg(){return dark?0xff101827:0xfffffbea;} int fg(){return dark?Color.WHITE:0xff152238;} int card(){return dark?0xff202c40:Color.WHITE;} int accent(){return 0xff1676c9;}
 @Override public boolean dispatchTouchEvent(MotionEvent event){
  if("Kalender".equals(screen)){
   if(calendarScale==null)calendarScale=new android.view.ScaleGestureDetector(this,new android.view.ScaleGestureDetector.SimpleOnScaleGestureListener(){
    @Override public boolean onScale(android.view.ScaleGestureDetector detector){float next=Math.max(.65f,Math.min(2.2f,calendarZoom*detector.getScaleFactor()));if(Math.abs(next-calendarZoom)>.005f)calendarZoom=next;return true;}
    @Override public void onScaleEnd(android.view.ScaleGestureDetector detector){pinchInProgress=true;show("Kalender");}
   });
   if(event.getActionMasked()==MotionEvent.ACTION_DOWN){pinchInProgress=false;gestureX=event.getRawX();gestureY=event.getRawY();gestureSwiped=false;}
   if(event.getPointerCount()>1)pinchInProgress=true;
   calendarScale.onTouchEvent(event);
   if(pinchInProgress){if(event.getActionMasked()==MotionEvent.ACTION_UP||event.getActionMasked()==MotionEvent.ACTION_CANCEL)pinchInProgress=false;return true;}
  }
  if("Kalender".equals(screen) && event.getActionMasked()==MotionEvent.ACTION_UP){
   float dx=event.getRawX()-gestureX,dy=event.getRawY()-gestureY;
   if(Math.abs(dx)>dp(65)&&Math.abs(dx)>Math.abs(dy)*1.3f){shiftCalendar(dx<0?1:-1);return true;}
  }
  return super.dispatchTouchEvent(event);
 }
 @Override public void onCreate(Bundle b){super.onCreate(b);db=new Db(this);android.content.SharedPreferences p=getPreferences(0);dark=p.getBoolean("dark",false);timerStart=p.getLong("timer",0);String l=p.getString("logo","");if(!l.isEmpty())logo=Uri.parse(l);BackupReceiver.schedule(this);show("Startseite");}
 static String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.GERMANY).format(new Date());} static String now(){return new SimpleDateFormat("HH:mm",Locale.GERMANY).format(new Date());} static String money(double n){return String.format(Locale.GERMANY,"%.2f",n);} static double num(String s){try{return Double.parseDouble(s.trim().replace(",","."));}catch(Exception e){return 0;}} static double hours(String a,String b,int pause){try{SimpleDateFormat f=new SimpleDateFormat("HH:mm",Locale.GERMANY);long d=f.parse(b).getTime()-f.parse(a).getTime();if(d<0)d+=86400000;return Math.max(0,d/3600000.0-pause/60.0);}catch(Exception e){return 0;}}
 TextView text(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(fg());t.setPadding(8,10,8,10);if(bold)t.setTypeface(null,1);return t;}
