 String exportFrom="",exportTo="",exportCustomer="",exportProject="",exportStatus="";
 String safeName(String s){return s.replaceAll("[^a-zA-Z0-9äöüÄÖÜß_-]","-").replaceAll("-+","-");}
 String exportFilename(int code){StringBuilder n=new StringBuilder("Projekt-Erfassung");if(!exportFrom.isEmpty())n.append("_ab-").append(safeName(exportFrom));if(!exportTo.isEmpty())n.append("_bis-").append(safeName(exportTo));if(!exportCustomer.isEmpty())n.append("_").append(safeName(exportCustomer));if(!exportProject.isEmpty())n.append("_").append(safeName(exportProject));if(!exportStatus.isEmpty())n.append("_").append(safeName(exportStatus));return n.append(code==PDF?".pdf":".xlsx").toString();}
 void exportDialog(int code){LinearLayout fields=vertical();fields.setPadding(24,8,24,8);EditText from=new EditText(this),to=new EditText(this);from.setHint("Von: TT.MM.JJJJ (leer = alle)");to.setHint("Bis: TT.MM.JJJJ (leer = alle)");fields.addView(from);fields.addView(to);Cursor c=db.query("SELECT DISTINCT c.name,p.name FROM projects p JOIN customers c ON c.id=p.customer_id ORDER BY c.name,p.name");java.util.ArrayList<String> clients=new java.util.ArrayList<>(),projs=new java.util.ArrayList<>();clients.add("Alle Kunden");projs.add("Alle Projekte");while(c.moveToNext()){if(!clients.contains(c.getString(0)))clients.add(c.getString(0));if(!projs.contains(c.getString(1)))projs.add(c.getString(1));}c.close();Spinner client=new Spinner(this),project=new Spinner(this),status=new Spinner(this);client.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,clients));project.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,projs));status.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Alle Status","Offen","Abgerechnet","Bezahlt"}));fields.addView(client);fields.addView(project);fields.addView(status);new AlertDialog.Builder(this).setTitle("Export filtern").setView(fields).setNegativeButton("Abbrechen",null).setPositiveButton("Exportieren",(d,w)->{exportFrom=from.getText().toString().trim().isEmpty()?"":isoDate(from.getText().toString().trim());exportTo=to.getText().toString().trim().isEmpty()?"":isoDate(to.getText().toString().trim());exportCustomer=client.getSelectedItemPosition()==0?"":clients.get(client.getSelectedItemPosition());exportProject=project.getSelectedItemPosition()==0?"":projs.get(project.getSelectedItemPosition());exportStatus=status.getSelectedItemPosition()==0?"":status.getSelectedItem().toString();create(code,code==PDF?"application/pdf":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",exportFilename(code));}).show();}
 void create(int code,String type,String filename){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(type).addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,filename);startActivityForResult(i,code);}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{if(request==PROJECT_EXPORT){try(java.io.InputStream in=new java.io.FileInputStream(new java.io.File(getFilesDir(),"project_files/"+pendingExport));java.io.OutputStream out=getContentResolver().openOutputStream(uri)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}toast("Datei exportiert");return;}if(request==BACKUP_FOLDER){getContentResolver().takePersistableUriPermission(uri,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));getSharedPreferences("auto_backup",0).edit().putString("folder",uri.toString()).apply();BackupReceiver.write(this);BackupReceiver.schedule(this);toast("Sicherungsordner gespeichert");return;}if(request==PDF)Exports.pdf(this,db,uri,exportFrom,exportTo,exportCustomer,exportProject,exportStatus);else if(request==XLSX)Exports.xlsx(this,db,uri,exportFrom,exportTo,exportCustomer,exportProject,exportStatus);else if(request==FULL_BACKUP){BackupArchive.write(this,uri);}else if(request==FULL_RESTORE){new AlertDialog.Builder(this).setTitle("Komplette Sicherung wiederherstellen?").setMessage("Vorhandene Daten werden ersetzt.").setNegativeButton("Abbrechen",null).setPositiveButton("Wiederherstellen",(d,w)->{try{BackupArchive.restore(this,uri);toast("Wiederhergestellt");show("Startseite");}catch(Exception ex){toast("Wiederherstellung fehlgeschlagen: "+ex.getMessage());}}).show();return;}else if(request==BACKUP){try(java.io.OutputStream o=getContentResolver().openOutputStream(uri)){o.write(db.backup().toString(2).getBytes("UTF-8"));}}else if(request==RESTORE){new AlertDialog.Builder(this).setTitle("Daten ersetzen?").setMessage("Alle aktuellen Einträge, Kunden und Projekte werden durch die Sicherung ersetzt.").setNegativeButton("Abbrechen",null).setPositiveButton("Wiederherstellen",(d,w)->{try(java.io.InputStream in=getContentResolver().openInputStream(uri)){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);db.restore(new JSONArray(out.toString("UTF-8")));toast("Wiederhergestellt");show("Startseite");}catch(Exception ex){toast("Importfehler: "+ex.getMessage());}}).show();return;}else if(request==PROJECT_UPLOAD){saveProjectFile(uri);return;}else if(request==LOGO){getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);logo=uri;getPreferences(0).edit().putString("logo",uri.toString()).apply();show("Startseite");return;}toast("Datei gespeichert");}catch(Exception ex){toast("Fehler: "+ex.getMessage());}}

